  { name: 'DOWNTOWN', x: 1500, y: 0, w: 1800, h: 1200, tint: '#5d6b8a' },
  { name: 'NORTH HILLS', x: 3300, y: 0, w: 1500, h: 1200, tint: '#4d7a5a' },
