  { name: 'SOUTH BEACH', x: 3300, y: 1200, w: 1500, h: 1200, tint: '#8a7a4d' },
  { name: 'THE BAY', x: 0, y: 3080, w: 4800, h: 520, tint: '#1d5a74' },
